-- Run 13 of 13 — missing techniques referenced by cve_techniques junction
INSERT INTO techniques (
  technique_id, technique_name, tactic, tactic_id, difficulty,
  learning_paths, plain_explanation, risk_category, risk_description,
  boardroom_pitch, industry_impacts, detection_hints, mitigations,
  reflection_question, spot_the_risk
) VALUES
('T1133', 'External Remote Services', 'Initial Access', 'TA0001', 'Intermediate',
 ARRAY['Blue Team', 'Red Team'],
 'Attackers abuse legitimate remote access services — VPNs, Citrix, RDP gateways, or remote management tools — that are exposed to the internet to gain an initial foothold.',
 'Business Interruption',
 'Internet-facing remote access services are a prime target because they are intended to allow external connections. A vulnerability or stolen credential is all that is needed to enter.',
 'Our VPN and remote access infrastructure is both a business necessity and an attack surface. Every unpatched gateway or reused password is an open door. We must treat remote access as a perimeter unto itself.',
 '[{"industry":"Financial Services","description":"Exploitation of unpatched VPN appliance granting direct access to the trading network."},{"industry":"Healthcare","description":"Compromised remote desktop gateway used to access clinical systems from outside the hospital network."}]',
 ARRAY['Anomalous VPN login times or geographies','Failed authentication spikes on remote access portals','New device or certificate seen on remote access infrastructure'],
 ARRAY['Patch remote access appliances immediately on CVE disclosure','Multi-factor authentication on all remote access','Network access control limiting what remote sessions can reach'],
 'Why are VPN and remote access appliances disproportionately targeted compared to other internet-facing systems?',
 'A Pulse Secure VPN appliance running a version vulnerable to CVE-2021-22893 is internet-facing. No patch has been applied. Threat intel reports active exploitation of this CVE in the wild.'),

('T1189', 'Drive-by Compromise', 'Initial Access', 'TA0001', 'Intermediate',
 ARRAY['Blue Team', 'GRC Focus'],
 'Attackers compromise websites visited by targets and use browser or plugin vulnerabilities to silently install malware — the victim only has to visit the page.',
 'Direct Financial Loss',
 'A drive-by attack requires no user interaction beyond browsing. A legitimate website that has been compromised becomes a weapon against every visitor.',
 'Employees browsing legitimate business websites can silently install malware if their browser or plugins are unpatched. Patch management and web filtering are the primary controls against this invisible attack vector.',
 '[{"industry":"Technology","description":"Developer visits a compromised tech blog — an unpatched Chrome vulnerability installs a backdoor silently."},{"industry":"Financial Services","description":"Finance staff visiting a watering-hole site tailored to their industry — exploit kit drops credential stealer."}]',
 ARRAY['Exploit kit traffic signatures in web proxy logs','Unexpected child processes spawned by browser','Endpoint detection for in-memory payload execution'],
 ARRAY['Keep browsers and plugins fully patched','Web content filtering and reputation checks','Endpoint detection for browser-spawned malicious processes'],
 'Why are watering-hole attacks particularly effective against targeted industries?',
 'An employee visits an industry news site that was silently compromised. An unpatched browser plugin executes a drive-by exploit and installs a backdoor — no click, no download prompt.'),

('T1210', 'Exploitation of Remote Services', 'Lateral Movement', 'TA0008', 'Advanced',
 ARRAY['Red Team', 'Purple Team'],
 'Attackers exploit vulnerabilities in internal network services — SMB, RDP, or application servers — to move laterally from one system to another without needing credentials.',
 'Business Interruption',
 'Internal services that are never exposed externally are still vulnerable to lateral movement if an attacker already has a foothold. Network segmentation and internal patching are both required.',
 'Once inside the network, attackers exploit the same unpatched internal services we rely on daily. EternalBlue proved that a single worm-capable internal vulnerability can encrypt an entire organization in hours.',
 '[{"industry":"Manufacturing","description":"EternalBlue (MS17-010) exploitation spreading ransomware across a flat OT/IT network in minutes."},{"industry":"Healthcare","description":"Unpatched internal RDP vulnerability allowing lateral movement from a compromised workstation to clinical servers."}]',
 ARRAY['Internal exploit traffic signatures (e.g. SMB exploit patterns)','Lateral movement analytics detecting unusual service access','Patch compliance monitoring for internal-facing services'],
 ARRAY['Patch internal services — not just internet-facing ones','Network microsegmentation to limit lateral reachability','Intrusion detection on internal network segments'],
 'Why do organizations often patch internet-facing systems faster than internal services, and why is that dangerous?',
 'A ransomware strain enters via phishing and uses EternalBlue to spread across the flat internal network, reaching domain controllers and file servers within 20 minutes of initial execution.'),

('T1553', 'Subvert Trust Controls', 'Defense Evasion', 'TA0005', 'Advanced',
 ARRAY['Red Team', 'Blue Team'],
 'Attackers undermine the mechanisms used to verify software trust — code signing, certificate validation, or Gatekeeper — so their malicious code appears legitimate and is allowed to run.',
 'Business Interruption',
 'When attackers subvert code signing or certificate trust, the OS and security tools believe their malware is legitimate software. Trust model integrity is foundational to every other security control.',
 'Our entire software security model depends on trust chains — signed certificates, verified publishers, OS security checks. When attackers subvert these, our defenses believe they are approving legitimate software.',
 '[{"industry":"Technology","description":"Stolen code signing certificate used to sign malware that passes all endpoint security checks as a trusted application."},{"industry":"Government","description":"Malicious driver signed with a compromised WHQL certificate loaded on classified workstations without triggering security alerts."}]',
 ARRAY['Certificate revocation monitoring','Unexpected new trusted root certificates','Code signing certificate anomaly detection (unusual issuer, short validity)'],
 ARRAY['Certificate pinning for critical software','Monitor certificate transparency logs for brand abuse','Revoke compromised signing certificates immediately'],
 'Why does subverting code signing provide attackers such a significant advantage over other evasion techniques?',
 'An EDR alert shows a new root certificate was installed silently. Subsequent malware signed by that certificate passes all security validation and is treated as trusted software.'),

('T1557', 'Adversary-in-the-Middle', 'Credential Access', 'TA0006', 'Advanced',
 ARRAY['Red Team', 'Blue Team'],
 'Attackers position themselves between two communicating parties — intercepting, reading, and potentially modifying traffic — to steal credentials, session tokens, or sensitive data.',
 'Direct Financial Loss',
 'A man-in-the-middle attack gives the attacker everything — credentials, session cookies, sensitive data — without compromising either endpoint. Encryption only helps if certificate validation is enforced.',
 'When attackers sit between our systems and our users, they see everything — passwords, session tokens, financial transactions. Certificate validation, network segmentation, and encrypted protocols are our defenses.',
 '[{"industry":"Financial Services","description":"ARP poisoning on a trading floor network intercepting cleartext authentication to internal financial systems."},{"industry":"Healthcare","description":"HTTPS interception via rogue certificate capturing clinician credentials on an unsegmented hospital network."}]',
 ARRAY['ARP spoofing detection on network segments','Unexpected certificate changes in TLS sessions','Rogue DHCP server detection'],
 ARRAY['Enable SMB signing and LDAP signing to prevent relay','Deploy 802.1X network access control','Enforce strict certificate validation — no exceptions for self-signed'],
 'What is the difference between a passive eavesdropping AitM attack and an active session hijacking AitM attack?',
 'ARP cache poisoning redirects all traffic from the finance workstation through the attacker''s machine. The attacker captures NTLM authentication hashes and injects modified responses.')
ON CONFLICT (technique_id) DO NOTHING;
